param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
function Normalize($raw){if($raw.PSObject.Properties['value'] -and $raw.PSObject.Properties['Count']){@($raw.value)}else{@($raw)}}
function NextKey($items){$used=@($items|%{if(([string]$_.Key).Length -eq 1){[int][char][string]$_.Key}});foreach($n in 65..90){if($used -notcontains $n){return [char]$n}};throw 'no key'}
$temp=Join-Path $env:TEMP ('CodexAccountManager-isolation-test-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $temp|Out-Null;$file=Join-Path $temp 'accounts.json'
$base=@(
 [pscustomobject]@{Key='A';Email='a@example.test';Home='C:\Users\Alice\.codex';State='state-A';UserData='user-A'},
 [pscustomobject]@{Key='B';Email='b@example.test';Home='C:\Users\Alice\.codex-account-b';State='state-B';UserData='user-B'},
 [pscustomobject]@{Key='C';Email='c@example.test';Home='C:\Users\Alice\.codex-account-c';State='state-C';UserData='user-C'},
 [pscustomobject]@{Key='D';Email='d@example.test';Home='C:\Users\Alice\.codex-account-a';State='state-D';UserData='user-D'})
$base|ConvertTo-Json|Set-Content $file -Encoding UTF8;$items=Normalize (Get-Content $file -Raw|ConvertFrom-Json);$e=[string](NextKey $items);$items2=$items+[pscustomobject]@{Key=$e;Email='e@example.test';Home='C:\Users\Alice\.codex-account-e';State='state-E';UserData='user-E'};$f=[string](NextKey $items2);if($e-ne'E'-or$f-ne'F'){throw "Expected E/F, got $e/$f"};if(@($items2|? Home -eq 'C:\Users\Alice\.codex-account-e').Count-ne1){throw 'E path missing'};if(@($items2|? Home -eq 'C:\Users\Alice\.codex-account-f').Count-ne0){throw 'F path unexpectedly present'};$failed=$false;try{if(@($items2|? Key -eq 'A').Count){throw 'duplicate id'}}catch{$failed=$true};if(-not$failed){throw 'duplicate id was accepted'};$failed=$false;try{if(@($items2|? Home -eq 'C:\Users\Alice\.codex-account-a').Count){throw 'duplicate home'}}catch{$failed=$true};if(-not$failed){throw 'duplicate home was accepted'};$items2|ConvertTo-Json -Depth 4|Set-Content $file -Encoding UTF8;$round=Normalize (Get-Content $file -Raw|ConvertFrom-Json);if(@($round|? Key -eq 'E').Count-ne1){throw 'E disappeared after save'};$items3=$round+[pscustomobject]@{Key='F';Email='f@example.test';Home='C:\Users\Alice\.codex-account-f';State='state-F';UserData='user-F'};$items3|ConvertTo-Json -Depth 4|Set-Content $file -Encoding UTF8;$round2=Normalize (Get-Content $file -Raw|ConvertFrom-Json);[pscustomobject]@{Result='PASS';NextIds='E,F';AtoDPreserved=(@($round2|? {$_.Key -in @('A','B','C','D')}).Count -eq 4);EAndF=@($round2|? {$_.Key -in @('E','F')}).Count;TempRegistry=$file}|ConvertTo-Json -Compress
